        g=ET.SubElement(ET.SubElement(r,'planView'),'geometry',s='0',x=str(x),y=str(y),hdg=str(hdg),length=str(length))
        ET.SubElement(g,'arc',curvature=str(curvature)) if curvature else ET.SubElement(g,'line')
